package com.match3vision.analyzer.hud

/** Binary glyph templates. A frame that does not match is left unread. */
internal object Glyphs {
    data class Template(val name: String, val width: Int, val height: Int, val bits: String)

    val all: List<Template> = listOf(
        Template("d0", 8, 12, "001111000111111001100110110000111100001111000011110000111100001111000011011001100111111000111100"),
        Template("d1", 6, 12, "000111001111011111110111000111000111000111000111000111000111000111000111"),
        Template("d2", 8, 12, "001111000111111001100111000001110000011100000110000011000001110000111000011100001111111111111111"),
        Template("d3", 8, 12, "001111000111111001000111000001100000111000111100001111100000011100000011100001111111111001111100"),
        Template("d4", 9, 12, "000001100000011100000011100000111100001101100001101100011001100111001100111111111000011110000001100000001100"),
        Template("d5", 8, 12, "011111100111111011100000111000001111110011111110000011110000011100000111100011111111111011111000"),
        Template("d6", 8, 12, "000111100011111001110000011000001101110011111110111001111100001111000011011001110111111000111100"),
        Template("d7", 8, 12, "111111111111111100000111000001100000011000001100000011000001110000011000001110000011000000110000"),
        Template("d8", 8, 12, "001111000111111001100111011001110111111000111100011111100110011111000011111001110111111000111100"),
        Template("d9", 8, 12, "001111000111111011100110110000111100001111100111011111110011101100000011000011100111110001111000"),
        Template("your", 79, 12, ""),
        Template("opponent", 101, 12, ""),
        Template("time", 78, 12, ""),
        Template("full", 38, 12, ""),
        Template("activate", 76, 12, ""),
        Template("multiplier", 98, 12, ""),
        Template("slash", 6, 12, "000011000011000010000110000110001100001100001100011000011000011000110000"),
        Template("f0", 24, 12, "001111000000011111111111011111100000011011111111011001110000011000000111111000110000110000000110111000110000110000000110111000110000110000001100111000110001100000001100111000110001100000011100111000110001000000011000011001110011000000111000011111100011000000110000001111000110000001110000"),
        Template("f1", 24, 12, "000110000000011111111111001110000000111011111111011110000000110000000111110110000000110000000110000110000001100000001110000110000001100000001100000110000001100000011100000110000001000000011000000110000011000000011000000110000011000000110000000110000110000000110000000110000110000001110000"),
        Template("f2", 24, 12, "001111000000011111111111011111100000011011111111011001110000011000000111000000110000110000000110000001110000110000000110000001100000110000001100000011100001100000001100000111000001100000011100001110000001000000011000011100000011000000111000111111110011000000110000111111110110000001110000"),
        Template("f3", 24, 12, "001111000000011111111111011111100000011011111111010001110000011000000111000001110000110000000110000011100000110000000110001111000000110000001100001111100001100000001100000001110001100000011100000000110001000000011000100001110011000000111000111111100011000000110000011111000110000001110000"),
        Template("f4", 24, 12, "000001100000011111111111000011100000011011111111000111100000011000000111000111100000110000000110001101100000110000000110001001100000110000001100011001100001100000001100110001100001100000011100111111110001000000011000000011110011000000111000000001100011000000110000000001100110000001110000"),
        Template("f5", 24, 12, "011111100000011111111111011111100000011011111111111000000000011000000111111000000000110000000110111111000000110000000110111111100001110000001100000011110001100000001100000001110001100000011100000001110011000000011000100011110011000000111000111111100111000000110000111110000110000001110000"),
        Template("f6", 24, 12, "000111100000011111111111001111100000011011111111011100000000011000000111011000000000110000000110111111100000110000000110111111110000110000001100111001110001100000001100111000110001100000011100111000110001000000011000011001110011000000111000011111100011000000110000000111000110000001110000"),
        Template("f7", 24, 12, "111111110000011111111111111111110000011011111111000000110000011000000111000001100000110000000110000001100000110000000110000011100000110000001100000011000001100000001100000111000001100000011100000111000001000000011000001110000011000000111000001100000011000000110000001100000110000001110000"),
        Template("activate-game", 96, 16, ""),
        Template("your-game", 80, 16, ""),
    )

    fun named(name: String): Template = all.first { it.name == name }

    val digits: List<Template> = all.filter { it.name.length == 2 && it.name[0] == 'd' }
    val phrases: List<Template> = listOf(named("your"), named("opponent"), named("time"))
    val cardWords: List<Template> = listOf(named("activate"), named("activate-game"), named("full")) + (0..7).map { named("f$it") }
    val yourGame: Template = named("your-game")
    val activateGame: Template = named("activate-game")
    val multiplierWord: Template = named("multiplier")

    fun paint(
        pixels: IntArray,
        width: Int,
        height: Int,
        left: Int,
        top: Int,
        template: Template,
        argb: Int,
    ) {
        for (y in 0 until template.height) {
            val py = top + y
            if (py !in 0 until height) continue
            for (x in 0 until template.width) {
                val px = left + x
                if (px !in 0 until width) continue
                if (template.bits[y * template.width + x] == '1') {
                    pixels[py * width + px] = argb
                }
            }
        }
    }

    fun similarity(sampleW: Int, sampleH: Int, sample: BooleanArray, template: Template): Double {
        if (sampleW < 2 || sampleH < 2) return 0.0
        val aspect = sampleW.toDouble() / sampleH
        val expected = template.width.toDouble() / template.height
        if (aspect < expected * 0.62 || aspect > expected * 1.45) return 0.0
        var same = 0
        val n = template.width * template.height
        for (y in 0 until template.height) {
            val sy = y * sampleH / template.height
            for (x in 0 until template.width) {
                val sx = x * sampleW / template.width
                val on = sample[sy * sampleW + sx]
                val want = template.bits[y * template.width + x] == '1'
                if (on == want) same++
            }
        }
        return same.toDouble() / n
    }

    data class Scored(val template: Template, val score: Double, val second: Double)

    /** Best template even when it is under the floor, so a live export can show the raw score. */
    fun scored(sampleW: Int, sampleH: Int, sample: BooleanArray, options: List<Template>): Scored? {
        var top: Template? = null
        var topScore = 0.0
        var second = 0.0
        for (template in options) {
            val score = similarity(sampleW, sampleH, sample, template)
            if (score > topScore) {
                second = topScore
                topScore = score
                top = template
            } else if (score > second) {
                second = score
            }
        }
        val winner = top ?: return null
        if (topScore <= 0.0) return null
        return Scored(winner, topScore, second)
    }

    fun accepted(scored: Scored?, floor: Double): Template? {
        if (scored == null || scored.score < floor) return null
        if (scored.score - scored.second < 0.04 && scored.second >= floor) return null
        return scored.template
    }

    fun best(sampleW: Int, sampleH: Int, sample: BooleanArray, options: List<Template>, floor: Double): Template? =
        accepted(scored(sampleW, sampleH, sample, options), floor)
}

